/**
 * Reviewed corporate-action events: carry a historical holding forward to a date, and tell which
 * security held a ticker on a date. TypeScript port of ERM3 `erm3/shared/security_events.py`; the
 * parity fixture `tests/fixtures/identity/security-events-parity.json` (generated by ERM3
 * `scripts/symbology/export_identity_parity_fixture.py`) pins the two together.
 *
 * Rows come from the Supabase mirror (`security_events`, `security_event_legs`) of the BWMACRO
 * seeds, which ERM3 validates before syncing. Quantities and ratios are exact fractions (BigInt),
 * so 0.241917 WBD per T share never picks up float error.
 */

// ---------- exact fractions ----------

export type Frac = { n: bigint; d: bigint };

function gcd(a: bigint, b: bigint): bigint {
  a = a < 0n ? -a : a;
  b = b < 0n ? -b : b;
  while (b) [a, b] = [b, a % b];
  return a || 1n;
}

export function frac(n: bigint, d: bigint = 1n): Frac {
  if (d === 0n) throw new Error("zero denominator");
  if (d < 0n) [n, d] = [-n, -d];
  const g = gcd(n, d);
  return { n: n / g, d: d / g };
}

export function parseDecimal(s: string | number): Frac {
  const t = String(s).trim();
  const m = /^(-?)(\d*)(?:\.(\d+))?$/.exec(t);
  if (!m || (m[2] === "" && !m[3])) throw new Error(`not a decimal: ${s}`);
  const digits = (m[2] || "0") + (m[3] ?? "");
  const scale = 10n ** BigInt((m[3] ?? "").length);
  return frac((m[1] ? -1n : 1n) * BigInt(digits), scale);
}

export const mul = (a: Frac, b: Frac) => frac(a.n * b.n, a.d * b.d);
export const add = (a: Frac, b: Frac) => frac(a.n * b.d + b.n * a.d, a.d * b.d);
export const sub = (a: Frac, b: Frac) => frac(a.n * b.d - b.n * a.d, a.d * b.d);
export const div = (a: Frac, b: Frac) => frac(a.n * b.d, a.d * b.n);
export const floor = (a: Frac) => frac(a.n >= 0n ? a.n / a.d : -((-a.n + a.d - 1n) / a.d));
export const ceil = (a: Frac) => frac(-floor(frac(-a.n, a.d)).n);
export const isZero = (a: Frac) => a.n === 0n;
export const eq = (a: Frac, b: Frac) => a.n === b.n && a.d === b.d;

/** Exact decimal string when the fraction terminates within 18 places, else 12 places rounded down. */
export function fracToString(a: Frac): string {
  let d = a.d;
  let k = 0;
  while (d % 10n === 0n) { d /= 10n; k++; }
  while (d % 2n === 0n) { d /= 2n; k++; }
  while (d % 5n === 0n) { d /= 5n; k++; }
  const places = d === 1n && k <= 18 ? k : 12;
  const scale = 10n ** BigInt(places);
  const neg = a.n < 0n;
  const v = ((neg ? -a.n : a.n) * scale) / a.d;
  const s = v.toString().padStart(places + 1, "0");
  const out = places ? `${s.slice(0, -places)}.${s.slice(-places)}`.replace(/\.?0+$/, "") : s;
  return (neg ? "-" : "") + out;
}

export function isExact(a: Frac): boolean {
  let d = a.d;
  for (const p of [2n, 5n]) while (d % p === 0n) d /= p;
  return d === 1n;
}

// ---------- model ----------

export type EventRow = {
  event_id: string;
  event_type: string;
  effective_date: string;
  legal_effective_date: string | null;
  record_date: string | null;
  ex_date: string | null;
  announced_date?: string | null;
  knowledge_date: string;
  source_form: string;
  source_accession: string | null;
  citation: string;
  evidence: string;
  review_status: string;
  reviewer?: string;
  reviewed_on?: string;
  supersedes_event_id: string | null;
};

export type LegRow = {
  event_id: string;
  leg: number;
  role: "input" | "output";
  outcome: "continues" | "new_security" | "cash" | "cancelled" | "unknown";
  input_leg: number | null;
  package: string;
  bw_sym_id: string | null;
  ticker: string;
  instrument: string;
  ratio_numerator: string | number | null;
  ratio_denominator: string | number | null;
  cash_per_unit: string | number | null;
  currency: string;
  fractional_treatment: string;
};

export type Leg = Omit<LegRow, "ratio_numerator" | "ratio_denominator" | "cash_per_unit"> & {
  ratio: Frac | null;
  cash_per_unit: Frac | null;
};

export type SecurityEvent = EventRow & { inputs: Leg[]; outputs: Leg[] };

export function buildEvents(eventRows: EventRow[], legRows: LegRow[]): SecurityEvent[] {
  const legs = new Map<string, Leg[]>();
  for (const r of legRows) {
    const ratio =
      r.ratio_numerator != null && r.ratio_denominator != null && r.ratio_numerator !== "" && r.ratio_denominator !== ""
        ? div(parseDecimal(r.ratio_numerator), parseDecimal(r.ratio_denominator))
        : null;
    const cash = r.cash_per_unit != null && r.cash_per_unit !== "" ? parseDecimal(r.cash_per_unit) : null;
    const leg: Leg = {
      ...r,
      leg: Number(r.leg),
      input_leg: r.input_leg == null || (r.input_leg as unknown) === "" ? null : Number(r.input_leg),
      ticker: (r.ticker ?? "").toUpperCase(),
      package: r.package ?? "",
      bw_sym_id: r.bw_sym_id || null,
      ratio,
      cash_per_unit: cash,
    };
    if (!legs.has(r.event_id)) legs.set(r.event_id, []);
    legs.get(r.event_id)!.push(leg);
  }
  const out: SecurityEvent[] = [];
  for (const e of eventRows) {
    const ls = (legs.get(e.event_id) ?? []).sort((a, b) => a.leg - b.leg);
    const inputs = ls.filter((l) => l.role === "input");
    if (!inputs.length) throw new Error(`${e.event_id}: no input leg`);
    const outputs = ls
      .filter((l) => l.role === "output")
      .map((o) => (o.input_leg == null && inputs.length === 1 ? { ...o, input_leg: inputs[0].leg } : o));
    out.push({ ...e, inputs, outputs });
  }
  return out.sort((a, b) => cmp(a.effective_date, b.effective_date) || cmp(a.event_id, b.event_id));
}

const cmp = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);

export const outputsFor = (e: SecurityEvent, input: Leg) => e.outputs.filter((o) => o.input_leg === input.leg);
export const terminalFor = (e: SecurityEvent, input: Leg) => !outputsFor(e, input).some((o) => o.outcome === "continues");

export function effectiveEvents(events: SecurityEvent[], knownAsOf?: string | null): SecurityEvent[] {
  const pool = events.filter((e) => !knownAsOf || e.knowledge_date <= knownAsOf);
  const replaced = new Set(
    pool.filter((e) => e.review_status === "accepted" && e.supersedes_event_id).map((e) => e.supersedes_event_id!),
  );
  return order(pool.filter((e) => e.review_status === "accepted" && !replaced.has(e.event_id)));
}

/** Date order; within a date, the event producing a listing (security, ticker) precedes the one consuming it. */
export function order(events: SecurityEvent[]): SecurityEvent[] {
  const byDate = new Map<string, SecurityEvent[]>();
  for (const e of events) {
    if (!byDate.has(e.effective_date)) byDate.set(e.effective_date, []);
    byDate.get(e.effective_date)!.push(e);
  }
  const out: SecurityEvent[] = [];
  for (const d of [...byDate.keys()].sort()) {
    const day = byDate.get(d)!.sort((a, b) => cmp(a.event_id, b.event_id));
    const consumers = new Map<string, SecurityEvent[]>();
    for (const e of day)
      for (const i of e.inputs) {
        const k = `${i.bw_sym_id}|${i.ticker}`;
        if (!consumers.has(k)) consumers.set(k, []);
        consumers.get(k)!.push(e);
      }
    for (const [k, es] of consumers)
      if (es.length > 1) throw new Error(`${d}: events ${es.map((e) => e.event_id)} all consume ${k} on the same date`);
    const after = new Map(day.map((e) => [e.event_id, new Set<string>()]));
    for (const e of day)
      for (const o of e.outputs)
        for (const c of consumers.get(`${o.bw_sym_id ?? ""}|${o.ticker}`) ?? [])
          if (c.event_id !== e.event_id) after.get(c.event_id)!.add(e.event_id);
    const done = new Set<string>();
    while (done.size < day.length) {
      const ready = day.filter((e) => !done.has(e.event_id) && [...after.get(e.event_id)!].every((x) => done.has(x)));
      if (!ready.length) throw new Error(`${d}: same-day events form a cycle`);
      for (const e of ready) { out.push(e); done.add(e.event_id); }
    }
  }
  return out;
}

function entitled(e: SecurityEvent, acquiredOn: string): boolean | null {
  if (e.ex_date) return acquiredOn < e.ex_date;
  if (acquiredOn < (e.record_date ?? e.effective_date)) return true;
  if (acquiredOn >= e.effective_date) return false;
  return null;
}

export type Holding = { bw_sym_id: string; ticker: string; instrument: string; quantity: Frac };
export type CashProceeds = {
  event_id: string;
  currency: string;
  amount: Frac | null;
  in_lieu_of_units: Frac | null;
  in_lieu_of: string | null;
};
/** One applied output leg: which security became which, by which event, at the exact ratio (`n/d`). */
export type TransitionStep = {
  event_id: string;
  event_type: string;
  effective_date: string;
  from_bw_sym_id: string;
  from_ticker: string;
  from_instrument: string;
  outcome: Leg["outcome"];
  to_bw_sym_id: string | null;
  to_ticker: string;
  to_instrument: string;
  ratio: string | null;
  quantity_in: Frac;
  quantity_out: Frac | null;
};

/** An exact fraction as `numerator/denominator` (reduced); never a rounded decimal. */
export const fracToRatio = (a: Frac): string => `${a.n}/${a.d}`;

export type EventResolution = {
  steps?: TransitionStep[];
  holdings: Holding[];
  cash: CashProceeds[];
  cancelled_by: string[];
  unknown_by: string[];
  applied_event_ids: string[];
  fractional_notes: string[];
  unresolved: string[];
  status: "held" | "cashed_out" | "cancelled" | "unknown" | "none";
};

export function applyEvents(
  events: SecurityEvent[],
  opts: {
    bw_sym_id: string;
    quantity: Frac;
    acquired_on: string;
    as_of: string;
    ticker?: string;
    instrument?: string;
    known_as_of?: string | null;
    elections?: Record<string, string>;
    fractions?: "apply" | "exact";
  },
): EventResolution {
  const { bw_sym_id, quantity, acquired_on, as_of } = opts;
  const fractions = opts.fractions ?? "apply";
  if (quantity.n < 0n) throw new Error("quantity must be non-negative");
  if (acquired_on > as_of) throw new Error("acquired_on is after as_of");
  const held = new Map<string, Holding>([
    [bw_sym_id, { bw_sym_id, ticker: (opts.ticker ?? "").toUpperCase(), instrument: opts.instrument ?? "", quantity }],
  ]);
  const cash: CashProceeds[] = [];
  const cancelled: string[] = [];
  const unknown: string[] = [];
  const unresolved: string[] = [];
  const applied: string[] = [];
  const notes: string[] = [];
  const steps: TransitionStep[] = [];
  for (const e of effectiveEvents(events, opts.known_as_of)) {
    if (e.effective_date > as_of) continue;
    for (const src of e.inputs) {
      const source = held.get(src.bw_sym_id!);
      if (!source) continue;
      const ent = src.bw_sym_id === bw_sym_id ? entitled(e, acquired_on) : true;
      if (ent === null) {
        unresolved.push(
          `${e.event_id}: acquired between record date and effective date; entitlement needs the ex-date`,
        );
        continue;
      }
      if (!ent) continue;
      let outs = outputsFor(e, src);
      const packages = [...new Set(outs.map((o) => o.package))].sort();
      if (!(packages.length === 1 && packages[0] === "")) {
        const choice = opts.elections?.[e.event_id];
        if (!choice || !packages.includes(choice)) {
          unresolved.push(`${e.event_id}: election among ${JSON.stringify(packages)} not given`);
          continue;
        }
        outs = outs.filter((o) => o.package === choice);
      }
      held.delete(src.bw_sym_id!);
      applied.push(e.event_id);
      for (const o of outs) {
        const step: TransitionStep = {
          event_id: e.event_id,
          event_type: e.event_type,
          effective_date: e.effective_date,
          from_bw_sym_id: source.bw_sym_id,
          from_ticker: source.ticker || src.ticker,
          from_instrument: source.instrument || src.instrument,
          outcome: o.outcome,
          to_bw_sym_id: o.bw_sym_id,
          to_ticker: o.ticker,
          to_instrument: o.instrument,
          ratio: o.ratio ? fracToRatio(o.ratio) : null,
          quantity_in: source.quantity,
          quantity_out: null,
        };
        steps.push(step);
        if (o.outcome === "continues" || o.outcome === "new_security") {
          let q = mul(source.quantity, o.ratio!);
          if (fractions === "apply" && (o.fractional_treatment === "cash_in_lieu" || o.fractional_treatment === "rounded_down")) {
            const whole = floor(q);
            if (!eq(whole, q) && o.fractional_treatment === "cash_in_lieu")
              cash.push({ event_id: e.event_id, currency: "", amount: null, in_lieu_of_units: sub(q, whole), in_lieu_of: o.bw_sym_id });
            q = whole;
          } else if (fractions === "apply" && o.fractional_treatment === "rounded_up") {
            q = ceil(q);
          } else if (o.fractional_treatment === "unknown" && !eq(q, floor(q))) {
            notes.push(`${e.event_id} leg ${o.leg}: fractional treatment unknown`);
          }
          const prev = held.get(o.bw_sym_id!);
          held.set(o.bw_sym_id!, {
            bw_sym_id: o.bw_sym_id!,
            ticker: o.ticker,
            instrument: o.instrument,
            quantity: prev ? add(prev.quantity, q) : q,
          });
          step.quantity_out = q;
        } else if (o.outcome === "cash") {
          cash.push({ event_id: e.event_id, currency: o.currency, amount: mul(source.quantity, o.cash_per_unit!), in_lieu_of_units: null, in_lieu_of: null });
        } else if (o.outcome === "cancelled") cancelled.push(e.event_id);
        else unknown.push(e.event_id);
      }
    }
  }
  const holdings = [...held.values()]
    .filter((h) => !isZero(h.quantity) || h.bw_sym_id === bw_sym_id)
    .sort((a, b) => Number(a.bw_sym_id !== bw_sym_id) - Number(b.bw_sym_id !== bw_sym_id) || cmp(a.bw_sym_id, b.bw_sym_id));
  const status =
    unknown.length || unresolved.length ? "unknown" : holdings.length ? "held" : cash.length ? "cashed_out" : cancelled.length ? "cancelled" : "none";
  return { holdings, cash, cancelled_by: cancelled, unknown_by: unknown, applied_event_ids: applied, fractional_notes: notes, unresolved, status, steps };
}

export type TickerWindow = { ticker: string; bw_sym_id: string; start: string | null; end: string | null };

export function tickerWindows(events: SecurityEvent[], knownAsOf?: string | null): TickerWindow[] {
  const opened = new Map<string, string | null>();
  const seen = new Set<string>();
  const out: TickerWindow[] = [];
  const key = (t: string, bw: string) => `${t}|${bw}`;
  for (const e of effectiveEvents(events, knownAsOf)) {
    const d = e.effective_date;
    for (const i of e.inputs) {
      const k = key(i.ticker, i.bw_sym_id!);
      let start: string | null;
      if (opened.has(k)) { start = opened.get(k)!; opened.delete(k); }
      else start = seen.has(k) ? d : null;
      seen.add(k);
      if (start === null || start < d) out.push({ ticker: i.ticker, bw_sym_id: i.bw_sym_id!, start, end: d });
    }
    for (const o of e.outputs)
      if (o.outcome === "continues" || o.outcome === "new_security") {
        const k = key(o.ticker, o.bw_sym_id!);
        seen.add(k);
        opened.set(k, d);
      }
  }
  for (const [k, start] of opened) {
    const [ticker, bw] = k.split("|");
    out.push({ ticker, bw_sym_id: bw, start, end: null });
  }
  return out.sort((a, b) => cmp(a.ticker, b.ticker) || cmp(a.start ?? "", b.start ?? "") || cmp(a.bw_sym_id, b.bw_sym_id));
}

export type TickerOwnership = {
  status: "reviewed" | "before_first_event" | "ambiguous" | "none";
  bw_sym_id: string | null;
  candidates: string[];
};

export function historicalTickerOwner(
  events: SecurityEvent[],
  ticker: string,
  heldOn: string,
  knownAsOf?: string | null,
): TickerOwnership {
  const t = ticker.trim().toUpperCase();
  const hits = tickerWindows(events, knownAsOf).filter(
    (w) => w.ticker === t && (w.start === null || w.start <= heldOn) && (w.end === null || heldOn < w.end),
  );
  const ids = [...new Set(hits.map((h) => h.bw_sym_id))].sort();
  if (!ids.length) return { status: "none", bw_sym_id: null, candidates: [] };
  if (ids.length > 1) return { status: "ambiguous", bw_sym_id: null, candidates: ids };
  return { status: hits.every((h) => h.start !== null) ? "reviewed" : "before_first_event", bw_sym_id: ids[0], candidates: ids };
}
